export function getMapObjectTypes(spaceId: Ref<string | undefined>): Ref<MapObjectType[]> {
  if (!spaceId) {
    return ref(defaultMapObjectTypes);
  }
  const { data: customMapObjectTypes } = useFind(
    'mapObjectTypes',
    computed(() => ({ query: { spaceId: spaceId.value } })),
  );

  const mapObjectTypes = computed<MapObjectType[]>(() => [
    ...defaultMapObjectTypes,
    ...customMapObjectTypes.value.map((mapObjectType) => ({
      name: mapObjectType.name,
      viewBox: mapObjectType.viewBox,
      paths: mapObjectType.paths,
      bgPaths: mapObjectType.bgPaths,
    })),
  ]);

  return mapObjectTypes;
}

type UseNewMapObject = {
  addMapObject: () => Promise<void>;
  resetNewMapObjectId: () => void;
  selectedMapObjectType: Ref<MapObjectType>;
};

// set id of unsaved added mapObject to a negative number to distinguish it from saved mapObjects
let newMapObjectId = 0;

export function isNewMapObject(mapObject: Model.MapObject): boolean {
  if (Number(mapObject._id) < 0) {
    return true;
  }
  return false;
}

export default function useNewMapObject(
  mapObjects: Ref<Model.MapObject[]>,
  selectMapObject: (id: string | null) => Promise<void>,
): UseNewMapObject {
  const { spaceId } = useCurrentSpace();
  const selectedMapObjectType = ref<MapObjectType>(getMapObjectTypes(spaceId).value[1]);
  async function addMapObject() {
    if (!spaceId.value) {
      throw new Error('Unexpected: A space must be selected');
    }

    newMapObjectId--;
    const newMapObject = {
      _id: String(newMapObjectId),
      xPos: 0,
      yPos: 0,
      rotation: 0,
      paths: selectedMapObjectType.value.paths,
      bgPaths: selectedMapObjectType.value.bgPaths || getBgPathsFromPaths(selectedMapObjectType.value.paths),
      type: selectedMapObjectType.value.name,
      space: spaceId.value,
    };
    mapObjects.value.push(newMapObject);
    await selectMapObject(newMapObject._id);
  }

  function resetNewMapObjectId() {
    newMapObjectId = 0;
  }

  return {
    addMapObject,
    resetNewMapObjectId,
    selectedMapObjectType,
  };
}
